#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Render versioned KO/EN/ES/FR/PT/DE/JA/ID notices from the audited, normalized inventory.
The input was imported from the user-supplied 2026-10-26 inventory, not resolved
again here. Original upstream texts are content-addressed and shared by all pages.
"""
from pathlib import Path
import html,json
ROOT=Path(__file__).resolve().parents[1];P=ROOT/'public';D=json.loads((P/'licenses/data/inventory.json').read_text());E=html.escape
C={
'en':dict(title='Open Source Licenses and Third-Party Notices',nav=['Privacy','Terms','Licenses'],version='Version',date='Effective date: October 26, 2026',contact='Contact',intro='Plena includes open-source software and platform SDKs. This inventory reflects app source HEAD 35596b94258d3d7c6b6e628685fc4c53a178656c, audited on October 26, 2026 (Flutter 3.44.0 / Dart 3.12.0). It is a resolved dependency inventory, not a claim that every graph entry ships in every mobile binary.',scope='Scope',scopeBody='The 134 runtime-closure Dart entries include alternative-platform packages. The 23 development-only packages and first-party plena_native are excluded from third-party runtime tables. google_maps_flutter_platform_interface is included because runtime packages require it transitively, despite its root dev declaration. Linux, Windows and web implementations in the lock graph are not Android/iOS native implementations. dbus, geoclue and gsettings are Linux-only; their MPL-2.0 notices do not license the Plena app as MPL.',direct='Direct Flutter/Dart dependencies',transitive='Transitive Flutter/Dart dependencies',android='Android native dependency resolution',androidBody='The table lists 122 releaseRuntimeClasspath modules and the separate desugar_jdk_libs 2.1.4 entry. BOM/platform/POM-only entries are identified; R8 or ABI filtering may exclude code. License labels retain the audited POM declarations or additional source evidence. Flutter engine entries retain their composite notices. desugar_jdk_libs uses GPL v2 with the Classpath Exception.',ios='iOS Swift packages',iosBody='The active iOS Maps plugin is google_maps_flutter_ios_sdk10 2.19.0. google_maps_flutter_ios 2.18.7 remains in the lock graph but is not the registered native implementation. The iOS Google Maps binary is 10.15.0, resolved through Swift Package Manager; the generated Flutter CocoaPods shim is not its version source. Apache-2.0 for the ios-maps-sdk repository describes integration source, not a blanket open-source license for the Google Maps binary or service.',maps='Maps and platform services',mapsBody='Map display uses Google Maps SDK for Android 20.0.0 and Maps SDK for iOS 10.15.0. The Flutter plugin’s BSD license does not replace Google Maps Platform terms. Google logos, map attribution and SDK third-party notices remain subject to SDK policies. Plena does not use the Google Places API; place-name search uses the operating system geocoder, and direct pin selection needs neither search nor reverse geocoding. Google Play services Location 21.3.0 and Google Play Billing 8.0.0 retain their platform/service terms. Apple EventKit, StoreKit, CoreLocation, Speech, Files and UserNotifications are OS APIs, not additional open-source packages or a Meroviq backend.',assets='Fonts and icons',assetsBody='Plena bundles Spoqa Han Sans Neo 1.100 (Copyright 2020 Spoqa, OFL-1.1) and Roboto 2.137 (Copyright 2011 Google Inc., Apache-2.0). Material Icons are provided by Google through Flutter; the audited SDK asset uses CC-BY-4.0, with unused glyphs potentially removed by tree shaking. cupertino_icons 1.0.9 is MIT. iOS SF Symbols and system fonts are supplied by Apple, not bundled font files. Original font copyright and license texts are linked below.',quotes='Quotations and holiday data',quotesBody='Plena includes 99 quotations whose source records are marked Public Domain. English originals come from public-domain editions. Korean and Spanish translations are written by Plena, not copied from modern copyrighted translations. Source metadata remains with the project. Holiday dates were generated from public jurisdictional calendars using python-holidays 0.83 (MIT), a generation tool rather than a mobile runtime dependency.',distribution='Original notices and distribution',distributionBody='Linked LICENSE/NOTICE texts remain in their original language and retain their copyright notices, conditions and disclaimers. POM files are license-declaration evidence, not substitutes for complete license texts. In particular, google_maps_flutter_web 0.6.5 retains both Flutter BSD-3-Clause and the MIT notice for to_screen_location. Flutter engine notices are composite and are not reduced to one SPDX label. Required notices must also remain in the distributed app; this website update does not certify a new binary build. Regenerate this inventory when dependency resolution changes.',headers=['Component','Resolved version','License / status','Original text / evidence'],previous='Previous version (1.0, English / Korean)',data='Audited inventory (JSON)',original='Original text',metadata='POM metadata',repo='Repository',kind='Resolution type',kinds=['Binary AAR/JAR','Platform / POM-only node','Separate desugaring dependency'],special='Repository integration source: Apache-2.0; Google Maps binary/service: Google Maps Platform agreement',tableLabel='Dependency table; scroll horizontally if needed'),
'ko':dict(title='오픈소스 라이선스 및 제3자 고지',nav=['개인정보처리방침','이용약관','라이선스'],version='버전',date='시행일: 2026년 10월 26일',contact='문의',intro='Plena는 오픈소스 소프트웨어와 플랫폼 SDK를 포함합니다. 이 목록은 앱 소스 HEAD 35596b94258d3d7c6b6e628685fc4c53a178656c를 2026년 10월 26일 감사한 결과입니다(Flutter 3.44.0 / Dart 3.12.0). 확정 의존성 목록이며 그래프의 모든 항목이 모든 모바일 바이너리에 포함된다는 뜻은 아닙니다.',scope='범위',scopeBody='런타임 의존성 폐쇄의 Dart 134개 항목에는 다른 플랫폼용 패키지도 포함됩니다. 개발 전용 23개와 자체 코드 plena_native는 제3자 런타임 표에서 제외합니다. google_maps_flutter_platform_interface는 루트의 dev 선언과 별개로 런타임 패키지가 전이적으로 필요로 하므로 포함합니다. 잠금 그래프의 Linux·Windows·웹 구현은 Android/iOS 네이티브 구현이 아닙니다. dbus·geoclue·gsettings는 Linux 전용이며 해당 MPL-2.0 고지가 Plena 앱 전체에 MPL을 적용하는 것은 아닙니다.',direct='직접 Flutter/Dart 의존성',transitive='전이 Flutter/Dart 의존성',android='Android 네이티브 의존성 해석 목록',androidBody='releaseRuntimeClasspath 모듈 122개와 별도의 desugar_jdk_libs 2.1.4 항목을 표시합니다. BOM·플랫폼·POM 전용 항목을 구분하며 R8·ABI 필터에 따라 코드가 제외될 수 있습니다. 라이선스 표기는 감사한 POM 선언 또는 추가 소스 근거를 유지합니다. Flutter 엔진의 복합 고지도 유지합니다. desugar_jdk_libs는 GPL v2와 Classpath Exception을 사용합니다.',ios='iOS Swift 패키지',iosBody='활성 iOS 지도 플러그인은 google_maps_flutter_ios_sdk10 2.19.0입니다. google_maps_flutter_ios 2.18.7은 잠금 그래프에 남지만 등록된 네이티브 구현은 아닙니다. iOS Google Maps 바이너리는 Swift Package Manager로 확정된 10.15.0이며 생성된 Flutter CocoaPods shim은 지도 버전의 근거가 아닙니다. ios-maps-sdk 저장소의 Apache-2.0은 통합 소스에 관한 것으로 Google Maps 바이너리·서비스 전체를 오픈소스로 분류하지 않습니다.',maps='지도 및 플랫폼 서비스',mapsBody='지도 표시는 Google Maps SDK for Android 20.0.0 및 Maps SDK for iOS 10.15.0을 사용합니다. Flutter 플러그인의 BSD 라이선스가 Google Maps Platform 약관을 대체하지 않습니다. Google 로고·지도 출처 표시와 SDK의 제3자 고지에는 SDK 정책이 적용됩니다. Plena는 Google Places API를 사용하지 않으며 장소명 검색은 운영체제 지오코더를 사용합니다. 직접 핀 선택에는 검색·역지오코딩이 필요하지 않습니다. Google Play services Location 21.3.0과 Google Play Billing 8.0.0은 각 플랫폼·서비스 약관을 유지합니다. Apple EventKit·StoreKit·CoreLocation·Speech·Files·UserNotifications는 OS API이며 추가 오픈소스 패키지나 Meroviq 백엔드가 아닙니다.',assets='폰트 및 아이콘',assetsBody='Plena는 Spoqa Han Sans Neo 1.100(Copyright 2020 Spoqa, OFL-1.1)과 Roboto 2.137(Copyright 2011 Google Inc., Apache-2.0)을 포함합니다. Material Icons는 Google이 Flutter를 통해 제공하며 감사한 SDK 자산의 라이선스는 CC-BY-4.0입니다. 사용하지 않는 글리프는 tree shaking으로 제외될 수 있습니다. cupertino_icons 1.0.9는 MIT입니다. iOS SF Symbols와 시스템 폰트는 Apple이 제공하며 번들 폰트 파일이 아닙니다. 원래 폰트 저작권·라이선스 전문은 아래에 연결합니다.',quotes='명언 및 공휴일 데이터',quotesBody='Plena에는 출처 기록이 Public Domain인 명언 99건이 포함됩니다. 영문 원문은 퍼블릭 도메인 판본이며 한국어·스페인어 번역은 Plena가 작성했고 현대 저작권 번역본에서 복사하지 않았습니다. 출처 메타데이터는 프로젝트에 유지합니다. 공휴일 날짜는 공개 관할 달력을 기준으로 python-holidays 0.83(MIT)을 사용해 생성했으며 모바일 런타임 의존성이 아닌 생성 도구입니다.',distribution='원문 고지 및 배포',distributionBody='연결된 LICENSE·NOTICE 전문은 원래 언어와 저작권·조건·면책 문구를 유지합니다. POM은 라이선스 선언 근거이며 전문을 대체하지 않습니다. 특히 google_maps_flutter_web 0.6.5의 Flutter BSD-3-Clause와 to_screen_location MIT 고지를 모두 보존합니다. Flutter 엔진 복합 고지를 하나의 SPDX로 축약하지 않습니다. 필요한 고지는 배포 앱에서도 유지해야 하며 이번 웹사이트 갱신은 새 바이너리 빌드의 준수 인증이 아닙니다. 의존성 해석이 바뀌면 이 목록을 다시 생성해야 합니다.',headers=['구성요소','확정 버전','라이선스 / 구분','원문 / 근거'],previous='이전 버전(1.0, 영어 / 한국어)',data='감사 목록(JSON)',original='원문',metadata='POM 메타데이터',repo='저장소',kind='해석 유형',kinds=['AAR/JAR 바이너리','플랫폼 / POM 전용 항목','별도 desugaring 의존성'],special='저장소 통합 소스: Apache-2.0; Google Maps 바이너리·서비스: Google Maps Platform 약관',tableLabel='의존성 표; 필요한 경우 가로로 스크롤하세요'),
'es':dict(title='Licencias de código abierto y avisos de terceros',nav=['Privacidad','Términos','Licencias'],version='Versión',date='Fecha de entrada en vigor: 26 de octubre de 2026',contact='Contacto',intro='Plena incluye software de código abierto y SDK de plataformas. Este inventario refleja el código de la aplicación en el commit 35596b94258d3d7c6b6e628685fc4c53a178656c, auditado el 26 de octubre de 2026 (Flutter 3.44.0 / Dart 3.12.0). Enumera las dependencias resueltas; no afirma que todas las entradas del grafo se distribuyan en todos los binarios móviles.',scope='Alcance',scopeBody='Las 134 entradas de Dart necesarias para la ejecución incluyen paquetes de otras plataformas. Se excluyen de las tablas de terceros los 23 paquetes exclusivos de desarrollo y el código propio plena_native. Se incluye google_maps_flutter_platform_interface porque los paquetes de ejecución lo requieren de forma transitiva, aunque se declare como dependencia de desarrollo en la raíz. Las implementaciones de Linux, Windows y web del grafo no son implementaciones nativas de Android/iOS. dbus, geoclue y gsettings son exclusivos de Linux; sus avisos MPL-2.0 no implican que la aplicación Plena esté licenciada bajo MPL.',direct='Dependencias directas de Flutter/Dart',transitive='Dependencias transitivas de Flutter/Dart',android='Resolución de dependencias nativas de Android',androidBody='La tabla enumera 122 módulos de releaseRuntimeClasspath y, por separado, desugar_jdk_libs 2.1.4. Se identifican las entradas BOM, de plataforma o solo POM; R8 o los filtros de ABI pueden excluir código. Las etiquetas de licencia conservan las declaraciones del POM auditado o las pruebas adicionales del código fuente. Se mantienen los avisos compuestos del motor de Flutter. desugar_jdk_libs utiliza GPL v2 con la excepción Classpath.',ios='Paquetes Swift de iOS',iosBody='El complemento de mapas activo en iOS es google_maps_flutter_ios_sdk10 2.19.0. google_maps_flutter_ios 2.18.7 permanece en el grafo, pero no es la implementación nativa registrada. El binario de Google Maps para iOS es la versión 10.15.0, resuelta mediante Swift Package Manager; el adaptador generado de Flutter para CocoaPods no determina esa versión. La licencia Apache-2.0 del repositorio ios-maps-sdk corresponde al código de integración y no convierte todo el binario ni el servicio de Google Maps en software de código abierto.',maps='Mapas y servicios de plataformas',mapsBody='Los mapas se muestran mediante Google Maps SDK for Android 20.0.0 y Maps SDK for iOS 10.15.0. La licencia BSD del complemento de Flutter no sustituye los términos de Google Maps Platform. Los logotipos de Google, las atribuciones de los mapas y los avisos de terceros del SDK siguen sujetos a las políticas del SDK. Plena no utiliza Google Places API; la búsqueda de nombres de lugares utiliza el geocodificador del sistema operativo y seleccionar directamente un marcador no requiere búsquedas ni geocodificación inversa. Google Play services Location 21.3.0 y Google Play Billing 8.0.0 conservan sus términos de plataforma o servicio. Apple EventKit, StoreKit, CoreLocation, Speech, Files y UserNotifications son API del sistema operativo, no paquetes adicionales de código abierto ni un servidor de Meroviq.',assets='Fuentes e iconos',assetsBody='Plena incluye Spoqa Han Sans Neo 1.100 (Copyright 2020 Spoqa, OFL-1.1) y Roboto 2.137 (Copyright 2011 Google Inc., Apache-2.0). Google proporciona Material Icons a través de Flutter; el recurso auditado del SDK utiliza CC-BY-4.0 y los glifos no utilizados pueden eliminarse al optimizar la aplicación. cupertino_icons 1.0.9 utiliza MIT. Apple proporciona SF Symbols y las fuentes del sistema de iOS; no se incluyen como archivos de fuentes en la aplicación. Los textos originales de copyright y licencia de las fuentes se enlazan a continuación.',quotes='Citas y datos de festivos',quotesBody='Plena incluye 99 citas cuyos registros de origen están marcados como dominio público. Los originales en inglés proceden de ediciones de dominio público. Plena ha redactado las traducciones al coreano y al español, sin copiarlas de traducciones modernas protegidas por derechos de autor. Los metadatos de las fuentes se conservan con el proyecto. Las fechas de festivos se generaron a partir de calendarios públicos de distintas jurisdicciones mediante python-holidays 0.83 (MIT), una herramienta de generación y no una dependencia de ejecución móvil.',distribution='Avisos originales y distribución',distributionBody='Los textos LICENSE y NOTICE enlazados se conservan en su idioma original, con sus avisos de copyright, condiciones y exclusiones de garantía. Los archivos POM acreditan las declaraciones de licencia, pero no sustituyen sus textos completos. En particular, google_maps_flutter_web 0.6.5 conserva tanto BSD-3-Clause de Flutter como el aviso MIT de to_screen_location. Los avisos compuestos del motor de Flutter no se reducen a una sola etiqueta SPDX. Los avisos exigidos también deben conservarse en la aplicación distribuida; esta actualización del sitio no certifica un nuevo binario. El inventario debe regenerarse cuando cambien las dependencias resueltas.',headers=['Componente','Versión resuelta','Licencia / condición','Texto original / prueba'],previous='Versión anterior (1.0, inglés / coreano)',data='Inventario auditado (JSON)',original='Texto original',metadata='Metadatos POM',repo='Repositorio',kind='Tipo de entrada',kinds=['Binario AAR/JAR','Entrada de plataforma / solo POM','Dependencia separada de desugaring'],special='Código de integración del repositorio: Apache-2.0; binario/servicio Google Maps: términos de Google Maps Platform',tableLabel='Tabla de dependencias; desplázate horizontalmente si es necesario')}
C['fr']=json.loads((ROOT/'scripts/licenses-fr.json').read_text())
assert set(C['fr']) == set(C['en']), 'French notice fields must match the existing language schema'
C['pt']=json.loads((ROOT/'scripts/licenses-pt.json').read_text())
assert set(C['pt']) == set(C['en']), 'Portuguese notice schema mismatch'
C['de']=json.loads((ROOT/'scripts/licenses-de.json').read_text())
assert set(C['de']) == set(C['en']), 'German notice schema mismatch'
C['ja']=json.loads((ROOT/'scripts/licenses-ja.json').read_text())
assert set(C['ja']) == set(C['en']), 'Japanese notice schema mismatch'
C['id']=json.loads((ROOT/'scripts/licenses-id.json').read_text())
assert set(C['id']) == set(C['en']), 'Indonesian notice schema mismatch'
VERSIONS={'privacy':'1.2','terms':'1.1','licenses':'1.1'}
def nav(lang):
 c=C[lang];return '<nav aria-label="Plena"><a href="/">Plena Legal</a>'+''.join(f'<a href="/{kind}/{lang}/v{VERSIONS[kind]}/">{label}</a>' for kind,label in zip(VERSIONS,c['nav']))+'</nav>'
def langs(kind,version,lang):
 return '<nav aria-label="Language / 언어 / Idioma / Langue">'+''.join(f'<a href="/{kind}/{l}/v{version}/" lang="{l}" hreflang="{l}"'+(' aria-current="page"' if l==lang else '')+'>'+name+'</a>' for l,name in [('ko','한국어'),('en','English'),('es','Español'),('fr','Français'),('pt','Português (Brasil)'),('de','Deutsch'),('ja','日本語'),('id','Bahasa Indonesia')])+'</nav>'
def table(rows,c):
 s='<div class="table-scroll" role="region" tabindex="0" aria-label="'+c['tableLabel']+'"><table><caption>'+c['tableLabel']+'</caption><thead><tr>'+''.join('<th scope="col">'+x+'</th>' for x in c['headers'])+'</tr></thead><tbody>'
 for r in rows:
  license='; '.join(r['licenses'])
  if r['name']=='ios-maps-sdk':license=c['special']
  links=' · '.join(f'<a href="{E(t["file"])}">{c["metadata"] if "POM" in t["source"] else c["original"]} {i+1}</a>' for i,t in enumerate(r['texts']))
  if r.get('url'):links+=' <a href="'+E(r['url'])+'">'+c['repo']+'</a>'
  name=E(r['name'])
  if r['ecosystem']=='Android':
   kind=r.get('kind','');ix=0 if kind=='binary AAR/JAR' else 2 if 'desugar' in r['name'] else 1
   name+='<br><small>'+c['kinds'][ix]+'</small>'
  s+='<tr><th scope="row"><code>'+name+'</code></th><td>'+E(r['version'])+'</td><td>'+E(license)+'</td><td>'+links+'</td></tr>'
 return s+'</tbody></table></div>'
def render(lang):
 c=C[lang];parts=[f'<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><title>Plena — {c["title"]}</title><meta name="viewport" content="width=device-width, initial-scale=1"><link rel="stylesheet" href="/assets/legal.css"></head><body><main>',nav(lang),langs('licenses','1.1',lang),'<h1>'+c['title']+'</h1>',f'<p class="meta">{c["version"]}: 1.1<br>{c["date"]}<br>{c["contact"]}: <a href="mailto:plena@meroviq.com">plena@meroviq.com</a></p>','<div class="notice">'+c['intro']+'</div>','<h2>'+c['scope']+'</h2><p>'+c['scopeBody']+'</p>']
 for key,eco,cond in [('direct','Dart',lambda r:r.get('directness')=='direct'),('transitive','Dart',lambda r:r.get('directness')=='transitive'),('android','Android',lambda r:True),('ios','iOS',lambda r:True),('assets','Assets',lambda r:True)]:
  parts.append('<h2>'+c[key]+'</h2>')
  if key+'Body' in c:parts.append('<p>'+c[key+'Body']+'</p>')
  rows=[r for r in D['records'] if r['ecosystem']==eco and cond(r)]
  if key=='direct':rows=[r for r in D['records'] if r['ecosystem']=='SDK']+rows
  parts.append(table(sorted(rows,key=lambda r:r['name']),c))
 for key in ['maps','quotes','distribution']:
  parts.append('<h2>'+c[key]+'</h2><p>'+c[key+'Body']+'</p>')
  if key=='maps':parts.append('<p><a href="https://cloud.google.com/maps-platform/terms">Google Maps Platform Terms</a> · <a href="https://policies.google.com/privacy">Google Privacy Policy</a> · <a href="https://developers.google.com/maps/documentation/android-sdk/policies">Android SDK</a> · <a href="https://developers.google.com/maps/documentation/ios-sdk/policies">iOS SDK</a></p>')
 parts.append('<p><a href="/licenses/data/inventory.json">'+c['data']+'</a> · <a href="/licenses/v1.0/">'+c['previous']+'</a></p><footer>'+nav(lang)+c['contact']+': <a href="mailto:plena@meroviq.com">plena@meroviq.com</a></footer></main></body></html>')
 page='\n'.join(parts)+'\n'
 if lang=='fr':
  page=page.replace('>Google Maps Platform Terms<','>Conditions de Google Maps Platform<').replace('>Google Privacy Policy<','>Règles de confidentialité de Google<')
 page=page.replace('lang="pt"','lang="pt-BR"')
 if lang=='pt':
  page=page.replace('>Google Maps Platform Terms<','>Termos da Plataforma Google Maps<').replace('>Google Privacy Policy<','>Política de Privacidade do Google<')
 if lang=='de':
  page=page.replace('>Google Maps Platform Terms<','>Nutzungsbedingungen der Google Maps Platform<').replace('>Google Privacy Policy<','>Datenschutzerklärung von Google<')
 if lang=='ja':
  page=page.replace('>Google Maps Platform Terms<','>Google Maps Platform利用規約<').replace('>Google Privacy Policy<','>Googleプライバシーポリシー<')
 if lang=='id':
  page=page.replace('>Google Maps Platform Terms<','>Persyaratan Google Maps Platform<').replace('>Google Privacy Policy<','>Kebijakan Privasi Google<')
 return page
for lang in C:
 d=P/f'licenses/{lang}/v1.1';d.mkdir(parents=True,exist_ok=True);(d/'index.html').write_text(render(lang))
